  #sky {
    position: fixed; inset: 0; width: 100%; height: 100%; display: block; z-index: 0;
    background: linear-gradient(to bottom, #131c39 0%, #3d3d69 17%, #8f6370 30%, #e8a077 37%, #fbd7b2 41%, #eed8c1 44%);
  }
  #scene-canvas { position: fixed; inset: 0; width: 100%; height: 100%; display: block; z-index: 1; }
  .vignette {
    position: fixed; inset: 0; z-index: 2; pointer-events: none;
    background: radial-gradient(ellipse at 50% 46%, rgba(0,0,0,0) 58%, rgba(26,18,38,0.3) 100%);
  }
  .caption {
    position: fixed; left: 26px; bottom: 22px; z-index: 3; pointer-events: none;
    font-family: Georgia, "Times New Roman", serif; color: #f8e6d2;
    text-shadow: 0 1px 8px rgba(40, 18, 30, 0.55);
