renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setClearColor(0x000000, 0);

const scene = new THREE.Scene();
// light warm haze: just enough to melt the valley floor, not enough to bleach
// Fuji's snow cap (a denser exponential fog washed the whole cone pale)
scene.fog = new THREE.FogExp2(0xf8d3b2, 0.0001);

