// vantage from the hilltop meadow: pagoda right of centre, cherry trees in front
const cameraAnchor = new THREE.Vector3(346, 47, 612);
camera.position.copy(cameraAnchor);
// look above the pagoda: summit crown floats high in the frame, haze below
const lookTarget = new THREE.Vector3(150, 455, -5400);

const sunDirection = new THREE.Vector3(-0.25, 0.18, -1).normalize();

